  const DURATION = 124.02;
  const LINES = [
    [0.8, "Did you know that Lord Shiva's fierce form, Kala Bhairava, is believed to manifest in eight powerful forms to guard the eight directions?", "tag", 8.06],
    [9.16, "These divine manifestations are known as the Ashta Bhairavas.", null, 12.58],
    [13.68, "Each form represents a different aspect of divine power…", null, 16.86],
    [17.76, "and together, they protect sacred spaces from negative forces.", null, 21.43],
    [22.53, "The first is Asitanga Bhairava, the guardian of the East.", "big", 25.97],
    [27.07, "The second is Ruru Bhairava, who protects the South-East.", "big", 30.77],
    [31.88, "The third is Chanda Bhairava, the fierce guardian of the South.", "big", 35.45],
    [36.55, "The fourth is Krodha Bhairava, who watches over the South-West.", "big", 40.01],
    [41.11, "The fifth is Unmatta Bhairava, the guardian of the West.", "big", 44.33],
    [45.43, "The sixth is Kapala Bhairava, who protects the North-West.", "big", 49.07],
    [50.17, "The seventh is Bhishana Bhairava, the terrifying guardian of the North.", "big", 54.3],
    [55.4, "And the eighth is Samhara Bhairava, the powerful force of destruction and transformation, who guards the North-East.", "big", 61.77],
    [62.87, "Together, these eight forms create a divine circle of protection around sacred places, especially the holy city of Kashi.", null, 69.99],
    [71.09, "They are also associated with eight Mother Goddesses, known as the Ashta Matrikas.", null, 75.49],
    [76.59, "Although their names and arrangements differ across some Hindu traditions, their central purpose remains the same…", null, 82.43],
    [83.33, "to protect, destroy evil, and uphold divine order.", null, 86.85],
    [87.95, "The Ashta Bhairavas teach us that divine power has many forms…", null, 91.42],
    [92.32, "but its purpose is one.", null, 93.66],
    [94.76, "To protect righteousness and destroy ignorance.", null, 97.35],
    [98.45, "But among all these manifestations, one form holds a special place in the hearts of devotees.", null, 103.91],
    [105.01, "A gentle yet powerful form of Bhairava, worshipped by those seeking protection and freedom from fear.", null, 110.68],
    [111.78, "Who is Batuk Bhairava…", "big", 113.11],
    [114.01, "and why is this childlike form of Lord Shiva so deeply worshipped?", "title", 117.73],
    [118.83, "That is the mystery of our next episode.", null, 121.02],
  ];
